import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

import type { ParseResult } from "./types.ts";

const parserDirectory = path.dirname(fileURLToPath(import.meta.url));
const typesModule = path.join(parserDirectory, "types");

/**
 * Writes the whole parse result as a TypeScript data file. The shape is the
 * contract, so the generated file is annotated with ParseResult and checked by
 * the project's normal type check.
 */
export function writeTypedDataFile(
  result: ParseResult,
  outputPath: string,
): string {
  const absoluteOutput = path.resolve(outputPath);

  if (path.extname(absoluteOutput).toLowerCase() !== ".ts") {
    throw new Error("The output file must end in .ts");
  }

  const relativeTypes = path
    .relative(path.dirname(absoluteOutput), typesModule)
    .split(path.sep)
    .join("/");
  const typesSpecifier = relativeTypes.startsWith(".")
    ? relativeTypes
    : `./${relativeTypes}`;
  const source = [
    "// Generated by scripts/parse-repo.ts. Do not edit by hand.",
    `import type { ParseResult } from "${typesSpecifier}";`,
    "",
    `export const parsedRepository: ParseResult = ${JSON.stringify(result, null, 2)};`,
    "",
  ].join("\n");

  fs.mkdirSync(path.dirname(absoluteOutput), { recursive: true });
  fs.writeFileSync(absoluteOutput, source, "utf8");

  return absoluteOutput;
}
